function getClip() {
  return { part: GM_getValue('clip_part',''), price: GM_getValue('clip_price','') };
}

let dockArmed = true;
let currentEngineCode = null;

function lookupProb(partNumber) {
  if (!currentEngineCode || !partNumber) return null;
  const val = PROB_DATA[(partNumber.toUpperCase().trim() + '_' + currentEngineCode)];
  if (!val) return null;
  return { conf: val[0], pct: parseInt(val.slice(1)) };
}

